## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/cholecystectomyLogic.ts`

```typescript
// Cholecystectomy Clinical Decision Logic
// Based on: SAGES Clinical Spotlight Review — Cholecystectomy (2022)
// Also: 2020 WSES Tokyo Guidelines; ACS NSQIP Best Practices

export interface CholecystectomyInput {
  age: number;
  sex: 'male' | 'female';

  // Indication
  indication: 'symptomatic-cholelithiasis' | 'acute-cholecystitis' | 'biliary-dyskinesia' | 'polyp' | 'other';

  // Symptoms
  biliaryColic: boolean;
  frequency: 'rare' | 'monthly' | 'weekly' | 'daily';
  painDuration: number; // months
  nausea: boolean;
  intolerance: boolean; // fatty food intolerance

  // Imaging
  ultrasoundConfirmed: boolean;
  gallstonesPresent: boolean;
  polypSize: number; // mm
  wallThickening: boolean;
  pericholecysticFluid: boolean;
  ejectionFraction: number; // % for HIDA scan (biliary dyskinesia)

  // Complications
  acuteCholecystitis: boolean;
  choledocholithiasis: boolean;
  cholangitis: boolean;
  gallstonePancreatitis: boolean;
  mirizzySyndrome: boolean;

  // Surgical risk
  asa: 1 | 2 | 3 | 4;
  priorAbdominalSurgery: boolean;
  cirrhosis: boolean;
  coagulopathy: boolean;
  pregnancy: boolean;
  pregnancyTrimester: 1 | 2 | 3 | 0;

  // Conservative treatment
  triedDietModification: boolean;
  triedMedications: boolean;
}

export interface CholecystectomyResult {
  candidacyScore: number;
  recommendation: 'Strongly Indicated' | 'Indicated' | 'Consider' | 'Not Indicated';
  urgency: 'Elective' | 'Semi-urgent (within 6 weeks)' | 'Urgent (within 72 hours)' | 'Emergent';
  approach: string;
  keyFindings: string[];
  warnings: string[];
  references: string[];
}

export function calculateCholecystectomyScore(input: CholecystectomyInput): CholecystectomyResult {
  const warnings: string[] = [];
  const keyFindings: string[] = [];
  let score = 0;
  let urgency: CholecystectomyResult['urgency'] = 'Elective';

  // Acute cholecystitis — urgent/semi-urgent
  if (input.acuteCholecystitis) {
    score += 40;
    urgency = 'Semi-urgent (within 6 weeks)';
    keyFindings.push('Acute cholecystitis — early laparoscopic cholecystectomy within 72 hours is preferred per Tokyo Guidelines 2020');
    if (input.cholangitis) {
      urgency = 'Urgent (within 72 hours)';
      warnings.push('Acute cholangitis — biliary drainage required urgently; cholecystectomy after stabilization');
    }
  }

  // Gallstone pancreatitis — urgent
  if (input.gallstonePancreatitis) {
    score += 40;
    urgency = 'Semi-urgent (within 6 weeks)';
    keyFindings.push('Gallstone pancreatitis — cholecystectomy during same admission (mild pancreatitis) or after resolution (severe) per SAGES guidelines');
  }

  // Symptomatic cholelithiasis
  if (input.biliaryColic && input.gallstonesPresent) {
    score += 30;
    keyFindings.push('Symptomatic cholelithiasis with confirmed gallstones — standard indication for elective cholecystectomy');
  }

  // Symptom frequency
  if (input.frequency === 'daily') { score += 15; keyFindings.push('Daily biliary colic — high symptom burden'); }
  else if (input.frequency === 'weekly') { score += 10; }
  else if (input.frequency === 'monthly') { score += 5; }

  // Duration
  if (input.painDuration >= 3) {
    score += 10;
    keyFindings.push(`${input.painDuration} months of symptomatic cholelithiasis — conservative treatment not effective`);
  }

  // Biliary dyskinesia
  if (input.indication === 'biliary-dyskinesia' && input.ejectionFraction < 35) {
    score += 25;
    keyFindings.push(`HIDA scan ejection fraction ${input.ejectionFraction}% — biliary dyskinesia; cholecystectomy indicated per SAGES guidelines`);
  }

  // Gallbladder polyp
  if (input.indication === 'polyp') {
    if (input.polypSize >= 10) {
      score += 35;
      keyFindings.push(`Gallbladder polyp ≥10mm — cholecystectomy indicated due to malignancy risk`);
    } else if (input.polypSize >= 6) {
      score += 15;
      keyFindings.push(`Gallbladder polyp ${input.polypSize}mm — surveillance vs cholecystectomy; consider surgery if symptomatic or risk factors`);
    }
  }

  // Choledocholithiasis
  if (input.choledocholithiasis) {
    score += 20;
    keyFindings.push('Choledocholithiasis — ERCP + cholecystectomy; laparoscopic common bile duct exploration if ERCP unavailable');
  }

  // Imaging findings
  if (input.wallThickening) {
    score += 10;
    keyFindings.push('Gallbladder wall thickening — increased urgency; consider malignancy workup');
  }

  // Conservative treatment
  if (input.triedDietModification) { score += 5; }

  // Surgical risk
  if (input.asa >= 4) {
    warnings.push('ASA Class IV — high surgical risk; multidisciplinary risk assessment required; percutaneous cholecystostomy may be preferred for acute cholecystitis');
    score -= 15;
  } else if (input.asa === 3) {
    warnings.push('ASA Class III — moderate surgical risk; optimize medical comorbidities pre-operatively');
  }

  if (input.cirrhosis) {
    warnings.push('Cirrhosis — significantly increased surgical risk; hepatology consultation required; Child-Pugh score should guide decision');
    score -= 10;
  }

  if (input.pregnancy) {
    if (input.pregnancyTrimester === 2) {
      keyFindings.push('Pregnancy (2nd trimester) — laparoscopic cholecystectomy safest in 2nd trimester if surgery required');
    } else if (input.pregnancyTrimester === 3) {
      warnings.push('3rd trimester pregnancy — increased surgical risk; conservative management preferred unless emergent');
    }
  }

  if (input.mirizzySyndrome) {
    warnings.push('Mirizzi syndrome — complex anatomy; experienced hepatobiliary surgeon recommended; open conversion may be required');
  }

  score = Math.max(0, Math.min(100, score));

  let recommendation: CholecystectomyResult['recommendation'];
  let approach: string;

  if (score >= 60) {
    recommendation = 'Strongly Indicated';
    approach = input.cirrhosis || input.mirizzySyndrome
      ? 'Laparoscopic cholecystectomy — experienced hepatobiliary surgeon; open conversion may be required'
      : 'Laparoscopic cholecystectomy — standard approach; single-incision laparoscopic (SILC) or robotic if available';
  } else if (score >= 35) {
    recommendation = 'Indicated';
    approach = 'Laparoscopic cholecystectomy — elective; optimize medical comorbidities pre-operatively';
  } else if (score >= 15) {
    recommendation = 'Consider';
    approach = 'Surgical consultation; complete workup; consider conservative management vs elective cholecystectomy';
  } else {
    recommendation = 'Not Indicated';
    approach = 'Conservative management; dietary modification; reassess in 3–6 months';
  }

  return {
    candidacyScore: score,
    recommendation,
    urgency,
    approach,
    keyFindings,
    warnings,
    references: [
      'Yokoe M, et al. Tokyo Guidelines 2018: Diagnostic Criteria and Severity Grading of Acute Cholecystitis. J Hepatobiliary Pancreat Sci. 2018;25(1):41-54. PMID: 29032636',
      'SAGES Clinical Spotlight Review: Cholecystectomy. 2022 — Laparoscopic cholecystectomy is the gold standard for symptomatic cholelithiasis and acute cholecystitis',
      'Gurusamy KS, et al. Early vs Delayed Laparoscopic Cholecystectomy for Acute Cholecystitis. Cochrane Database Syst Rev. 2013;6:CD005440. PMID: 23813477 — Early surgery reduces complications and hospital stay',
      'Stinton LM, Shaffer EA. Epidemiology of Gallbladder Disease: Cholelithiasis and Cancer. Gut Liver. 2012;6(2):172-187. PMID: 22570746',
    ],
  };
}
